package org.openbor.engine;
import android.app.*;import android.content.*;import android.database.Cursor;import android.graphics.Color;import android.graphics.Typeface;import android.net.Uri;import android.os.Bundle;import android.provider.OpenableColumns;import android.view.Gravity;import android.widget.*;import java.io.*;import java.util.Locale;
public class LauncherActivity extends Activity {
 private static final int PICK=41; private SharedPreferences p; private String lang="ru"; private TextView selected; private Button choose,start,settings;
 private int dp(int n){return (int)(n*getResources().getDisplayMetrics().density+.5f);}
 private String tr(String k){String[][] a={{"choose","Выбрать файл игры (.pak)","Ойын файлын таңдау (.pak)","Choose game file (.pak)"},{"start","Запустить игру","Ойынды іске қосу","Start game"},{"settings","Настройки управления","Басқару баптаулары","Control settings"},{"none","Файл игры не выбран","Ойын файлы таңдалмаған","No game file selected"},{"size","Размер кнопок","Батырмалар өлшемі","Button size"},{"opacity","Прозрачность","Мөлдірлік","Opacity"},{"save","Сохранить","Сақтау","Save"},{"cancel","Отмена","Болдырмау","Cancel"}};int c=lang.equals("kk")?2:lang.equals("en")?3:1;for(String[] r:a)if(r[0].equals(k))return r[c];return k;}
 @Override public void onCreate(Bundle b){super.onCreate(b);p=getSharedPreferences("base64e",0);lang=p.getString("language","ru");menu();}
 private Button btn(){Button b=new Button(this);b.setAllCaps(false);b.setTextColor(-1);b.setBackgroundTintList(android.content.res.ColorStateList.valueOf(Color.rgb(34,43,57)));return b;}
 private void menu(){LinearLayout box=new LinearLayout(this);box.setOrientation(1);box.setGravity(Gravity.CENTER);box.setPadding(dp(28),dp(20),dp(28),dp(20));box.setBackgroundColor(Color.rgb(13,17,24));
 TextView title=new TextView(this);title.setText("OpenBOR");title.setTextSize(34);title.setTypeface(Typeface.DEFAULT,1);title.setTextColor(-1);title.setGravity(17);box.addView(title);
 TextView sub=new TextView(this);sub.setText("NATIVE ANDROID PORT  •  base64E");sub.setTextColor(Color.rgb(93,185,255));sub.setTextSize(11);sub.setGravity(17);LinearLayout.LayoutParams sp=new LinearLayout.LayoutParams(-1,-2);sp.bottomMargin=dp(14);box.addView(sub,sp);
 Spinner langs=new Spinner(this);String[] codes={"ru","kk","en"};ArrayAdapter<String> ad=new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,new String[]{"Русский","Қазақша","English"});langs.setAdapter(ad);langs.setSelection(lang.equals("kk")?1:lang.equals("en")?2:0);box.addView(langs,new LinearLayout.LayoutParams(-1,dp(42)));langs.setOnItemSelectedListener(new android.widget.AdapterView.OnItemSelectedListener(){public void onItemSelected(android.widget.AdapterView<?> a,android.view.View v,int n,long id){lang=codes[n];p.edit().putString("language",lang).apply();labels();}public void onNothingSelected(android.widget.AdapterView<?> a){}});
 selected=new TextView(this);selected.setTextColor(Color.LTGRAY);selected.setGravity(17);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.topMargin=dp(12);box.addView(selected,lp);
 choose=btn();choose.setOnClickListener(v->pick());box.addView(choose,params());
 start=btn();start.setBackgroundTintList(android.content.res.ColorStateList.valueOf(Color.rgb(46,130,210)));start.setOnClickListener(v->launch());box.addView(start,params());
 settings=btn();settings.setOnClickListener(v->settings());box.addView(settings,params());
 TextView foot=new TextView(this);foot.setText("base64E");foot.setTextColor(Color.GRAY);foot.setGravity(17);box.addView(foot);setContentView(box);labels();}
 private LinearLayout.LayoutParams params(){LinearLayout.LayoutParams x=new LinearLayout.LayoutParams(-1,dp(48));x.topMargin=dp(5);x.bottomMargin=dp(5);return x;}
 private void labels(){if(selected==null)return;File[] f=new File(getExternalFilesDir(null),"Paks").listFiles((d,n)->n.toLowerCase(Locale.ROOT).endsWith(".pak"));selected.setText(f!=null&&f.length>0?f[0].getName():tr("none"));choose.setText(tr("choose"));start.setText(tr("start"));settings.setText(tr("settings"));}
 private void pick(){Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.addCategory(Intent.CATEGORY_OPENABLE);i.setType("*/*");startActivityForResult(i,PICK);}
 @Override protected void onActivityResult(int r,int c,Intent d){super.onActivityResult(r,c,d);if(r!=PICK||c!=RESULT_OK||d==null||d.getData()==null)return;Uri u=d.getData();String n=null;try(Cursor q=getContentResolver().query(u,null,null,null,null)){if(q!=null&&q.moveToFirst()){int x=q.getColumnIndex(OpenableColumns.DISPLAY_NAME);if(x>=0)n=q.getString(x);}}catch(Exception ignored){}if(n==null||!n.toLowerCase(Locale.ROOT).endsWith(".pak")){Toast.makeText(this,".pak file required",1).show();return;}try{File dir=new File(getExternalFilesDir(null),"Paks");if(!dir.exists()&&!dir.mkdirs())throw new IOException("Paks");File[] old=dir.listFiles((x,s)->s.toLowerCase(Locale.ROOT).endsWith(".pak"));if(old!=null)for(File f:old)if(!f.delete())throw new IOException("Cannot replace "+f.getName());File outFile=new File(dir,n);try(InputStream in=getContentResolver().openInputStream(u);OutputStream out=new FileOutputStream(outFile)){if(in==null)throw new IOException("Open failed");byte[] b=new byte[65536];int z;while((z=in.read(b))>0)out.write(b,0,z);}if(outFile.length()==0)throw new IOException("Empty file");p.edit().putString("game_file",n).apply();labels();Toast.makeText(this,"Game file added",0).show();}catch(Exception e){Toast.makeText(this,e.toString(),1).show();}}
 private void launch(){File[] f=new File(getExternalFilesDir(null),"Paks").listFiles((d,n)->n.toLowerCase(Locale.ROOT).endsWith(".pak"));if(f==null||f.length==0){pick();return;}startActivity(new Intent(this,GameActivity.class));}
 private void settings(){LinearLayout box=new LinearLayout(this);box.setPadding(dp(18),dp(8),dp(18),dp(8));box.setOrientation(1);SeekBar s=new SeekBar(this),o=new SeekBar(this);s.setMax(100);s.setProgress(p.getInt("size",100)-50);o.setMax(80);o.setProgress(p.getInt("opacity",65)-20);TextView sl=new TextView(this),ol=new TextView(this);box.addView(sl);box.addView(s);box.addView(ol);box.addView(o);Runnable u=()->{sl.setText(tr("size")+": "+(s.getProgress()+50)+"%");ol.setText(tr("opacity")+": "+(o.getProgress()+20)+"%");};SeekBar.OnSeekBarChangeListener l=new SeekBar.OnSeekBarChangeListener(){public void onProgressChanged(SeekBar b,int v,boolean f){u.run();}public void onStartTrackingTouch(SeekBar b){}public void onStopTrackingTouch(SeekBar b){}};s.setOnSeekBarChangeListener(l);o.setOnSeekBarChangeListener(l);u.run();new AlertDialog.Builder(this).setTitle(tr("settings")).setView(box).setPositiveButton(tr("save"),(a,b)->{int size=s.getProgress()+50,op=o.getProgress()+20;p.edit().putInt("size",size).putInt("opacity",op).apply();write(size,op,p.getInt("dpadX",0),p.getInt("dpadY",0),p.getInt("actionX",0),p.getInt("actionY",0));}).setNegativeButton(tr("cancel"),null).show();}
 private void write(int s,int o,int dx,int dy,int ax,int ay){try{File d=new File(getExternalFilesDir(null),"Saves");d.mkdirs();try(FileOutputStream f=new FileOutputStream(new File(d,"touch_settings.txt"))){f.write((s+"\n"+o+"\n"+dx+"\n"+dy+"\n"+ax+"\n"+ay+"\n").getBytes("UTF-8"));}}catch(Exception e){Toast.makeText(this,e.toString(),1).show();}}
}